import { freeze } from "@auaust/toolkit/object";

import { engrenage } from "#constants";
import type { Directory } from "#types/Directory";
import type { Files } from "#types/Files";

export const workflowsDirectory = ".github/workflows" satisfies Directory;

export const workflowFiles = freeze([
  "ci.yml",
  "publish.yml",
] as const) satisfies Files;

export const workflowTemplates = `${engrenage}/github/workflows`;

export const workflowHeader =
  "# Generated by `engrenage sync workflows`. Edits are overwritten on the next sync.\n\n";
